/// `newModel`: `ncdb model build`, after the lock's name, when it wrote the
/// first lock of a model; `id` is the new model id. A line per collection
/// follows.
pub(crate) fn new_model(id: impl std::fmt::Display) -> String {
    format!("model version 1, a new model ({id})")
}

/// `nodeNotStarted`: After the schema module's name, when `node` is on PATH but
/// cannot be started; `error` is the system's reason.
pub(crate) fn node_not_started(error: impl std::fmt::Display) -> String {
    format!("cannot start Node.js: {error}")
}

/// `cannotBeWritten`: After the lock's name, from `ncdb model build`, when the
/// lock cannot be written; `error` is the system's reason.
pub(crate) fn cannot_be_written(error: impl std::fmt::Display) -> String {
    format!("cannot be written: {error}")
}

/// `noSchemaFile`: After the schema module's name, from `ncdb model build` and
/// `ncdb model check`, when there is no file at `--model`.
pub(crate) const NO_SCHEMA_FILE: &str =
    "no such file; the schema module is ./model.ts unless --model names another.";

/// `optionNeedsPath`: `--model` or `--lock` given last, or followed by another
/// option; the usage follows.
pub(crate) fn option_needs_path(option: impl std::fmt::Display) -> String {
    format!("{option} needs a path")
}

/// `lockMissing`: `ncdb model check` when there is no lock at `--lock`.
pub(crate) fn lock_missing(lock: impl std::fmt::Display) -> String {
    format!("{lock}: missing; run ncdb model build.")
}

/// `unknownCommand`: `ncdb` run with a first word other than `model` or `help`;
