pub(crate) fn unknown_model_command(command: impl std::fmt::Display) -> String {
    format!("unknown command: model {command}")
}

/// `descriptionUnreadable`: After the schema module's name, when the SDK's
/// description of the model is no JSON this `ncdb` reads, as when the SDK and
/// `ncdb` are of different releases; `error` is the core's reason.
pub(crate) fn description_unreadable(error: impl std::fmt::Display) -> String {
    format!("the SDK described the model in a form this ncdb cannot read: {error}")
}

/// `noCommand`: `ncdb` run with no arguments; the usage follows.
pub(crate) const NO_COMMAND: &str =
    "no command";

/// `rewriteCanonical`: After `cli.outOfDate`, from `ncdb model check`, when the
/// lock describes the model but is not written in its canonical form, so
/// `build` would only rewrite it.
pub(crate) fn rewrite_canonical(version: impl std::fmt::Display) -> String {
    format!("rewrite it in its canonical form (model version stays {version})")
}

/// `refusedBreaksRules`: `ncdb model build` and `ncdb model check` when the
/// core refuses a first model; each refusal follows on a line of its own.
pub(crate) fn refused_breaks_rules(lock: impl std::fmt::Display) -> String {
    format!("{lock}: refused, the model breaks the rules (no lock is written)")
}

/// `handEdited`: After the lock's name, when the lock's `model.hash` does not
/// match its content.
pub(crate) const HAND_EDITED: &str =
    "its model.hash does not match its content, so it was edited by hand. Restore it from version control, and change the schema instead.";

/// `nodeVersionUnknown`: The `version` of `cli.nodeTooOld` when `node
/// --version` printed nothing.
pub(crate) const NODE_VERSION_UNKNOWN: &str =
    "of an unknown version";

/// `refusedNotAdditive`: `ncdb model build` and `ncdb model check` when the
/// core refuses the change against the previous lock; each refusal follows on a
/// line of its own.
pub(crate) fn refused_not_additive(lock: impl std::fmt::Display, version: impl std::fmt::Display) -> String {
    format!("{lock}: refused, the change is not additive (model version stays {version})")
}

/// `modelNeedsCommand`: `ncdb model` with nothing after it; the usage follows.
pub(crate) const MODEL_NEEDS_COMMAND: &str =
    "model needs a command: build or check";

/// `usage`: `ncdb --help`, `ncdb -h` or `ncdb help` prints it; after a usage
/// error, `ncdb` prints it below the error.
pub(crate) const USAGE: &str =
    "usage: ncdb model build [--model <path>] [--lock <path>]\u{a}       ncdb model check [--model <path>] [--lock <path>]\u{a}\u{a}build reads the schema module (--model, default ./model.ts, which exports\u{a}`model`) and the previous lock (--lock, default ./model.lock.json), refuses a\u{a}change that clients on the previous model could not keep, and writes the lock.\u{a}check does the same and writes nothing: it fails when the lock is missing or\u{a}out of date, or the change is refused. Both run the schema with Node.js 24 or\u{a}later, found on PATH.\u{a}";

/// `schemaExportsNoModel`: After the schema module's name, when the module
/// imports but exports no `model` made with `nc.model`.
pub(crate) const SCHEMA_EXPORTS_NO_MODEL: &str =
    "exports no model; export the model as `export const model = nc.model(...)`.";

/// `additive`: `ncdb model build`, the last line of a new model version's
/// report: the change is additive.
pub(crate) fn additive(from: impl std::fmt::Display, to: impl std::fmt::Display) -> String {
    format!("additive: clients on model version {from} keep every change written under version {to}.")
}

/// `unknownOption`: `ncdb model build` and `ncdb model check` given an option
/// other than `--model` or `--lock`; the usage follows.
pub(crate) fn unknown_option(option: impl std::fmt::Display) -> String {
    format!("unknown option: {option}")
}

/// `cannotBeRead`: After the lock's name, when the lock cannot be read from
/// disk, or is no lock JSON; `error` is the system's or the core's reason.
pub(crate) fn cannot_be_read(error: impl std::fmt::Display) -> String {
    format!("cannot be read: {error}")
}

/// `cannotBeOpened`: After the schema module's name, when its path cannot be
