pub(crate) fn cannot_be_opened(error: impl std::fmt::Display) -> String {
    format!("cannot be opened: {error}")
}

/// `nodeNotFound`: After the schema module's name, from `ncdb model build` and
/// `ncdb model check`, when no `node` is on PATH.
pub(crate) fn node_not_found(major: impl std::fmt::Display) -> String {
    format!("ncdb runs the schema with Node.js {major} or later, and found no `node` on PATH.")
}

/// `outOfDate`: `ncdb model check` when the lock differs from what `ncdb model
/// build` would write; `would` is what build would report, or
