pub(crate) fn out_of_date(lock: impl std::fmt::Display, would: impl std::fmt::Display) -> String {
    format!("{lock}: out of date; run ncdb model build. It would write {would}")
}

/// `descriptionsChanged`: `ncdb model build`, after the lock's name, when only
